Office.onReady((info) => {
  if (info.host === Office.HostType.Excel) {
    document.getElementById("connectButton").onclick = connectToServer;
    document.getElementById("fetchTablesButton").onclick = showTableSelection;
    document.getElementById("fetchSqlButton").onclick = showSqlInput;
    document.getElementById("fetchTableDataButton").onclick = fetchTableData;
    document.getElementById("fetchSqlDataButton").onclick = fetchSqlData;
  }
});

function connectToServer() {
  const baseUrl = document.getElementById("baseUrl").value;
  const accessToken = document.getElementById("accessToken").value;
  

  if (baseUrl && accessToken) {
    document.getElementById("dataOptions").style.display = "block";
  }
}

function showTableSelection() {
  const baseUrl = document.getElementById("baseUrl").value;
  const accessToken = document.getElementById("accessToken").value;
  
    document.getElementById('topinfo').style.display="none"

  console.log("Base URL:", baseUrl);
  console.log("Access Token:", accessToken);

  document.getElementById("tableSelection").style.display = "flex";
  document.getElementById("sqlQueryInput").style.display = "none";

  const tableList = document.getElementById("tableList");

  fetch(baseUrl + "/looker/tablenames/", {
    headers: {
      "authorization": accessToken,
      "Content-Type": "application/json"
    },
  })
    .then((response) => {
      console.log("Response status:", response);
      if (!response.ok) {
        throw new Error('Network response was not ok ' + response.statusText);
      }
      return response.json();
    })
    .then((data) => {
      console.log("Data received:", data);
      if (!Array.isArray(data)) {
        throw new Error('Expected an array but got ' + typeof data);
      }
      tableList.innerHTML = ""; // Clear existing options
      data.forEach((table) => {
        const option = document.createElement("option");
        option.value = table;
        option.text = table;
        tableList.appendChild(option);
      });
    })
    .catch((error) => {
      console.error('Error fetching table names:', error);
      tableList.innerHTML = `<option value="error">Error: ${error.message}</option>`;
    });
}

function showSqlInput() {
  document.getElementById("tableSelection").style.display = "none";
  document.getElementById("sqlQueryInput").style.display = "block";
}


