async function fetchTableData() {
  const baseUrl = document.getElementById("baseUrl").value;
  const accessToken = document.getElementById("accessToken").value;
  const tables = Array.from(document.getElementById("tableList").selectedOptions).map((option) => option.value);
  console.log(tables);
  console.log(typeof (tables));
  
  tables.forEach(async (table, index) => {
    try {
      console.log('table', table, typeof(table));
      let allData = [];
      let nextUrl = `${baseUrl}/looker/connector/${table}`;
      
      // Function to fetch data recursively
      async function fetchBatchData(url) {
        const response = await fetch(url, {
          headers: {
            authorization: accessToken,
          },
        });
        if (!response.ok) {
          throw new Error('Network response was not ok ' + response.statusText);
        }
        const apiResponse = await response.json();
        allData = allData.concat(apiResponse.data);

        if (apiResponse.next) {
          await fetchBatchData(apiResponse.next);
        }
      }

      // Fetch all data batches
      await fetchBatchData(nextUrl);

      // Process and add the data to Excel
      await Excel.run(async (context) => {
        let sheetName = table;
        
        
        let sheets = context.workbook.worksheets;
        sheets.load("items/name");
        await context.sync();

        const sheetNames = sheets.items.map(sheet => sheet.name);
        let originalSheetName = sheetName;
        let counter = 1;
        while (sheetNames.includes(sheetName)) {
          sheetName = originalSheetName + counter;
          counter++;
        }

        const sheet = context.workbook.worksheets.add(sheetName);

        // Set headers in row 1
        const headers = Object.keys(allData[0]);
        sheet.getRange("A1").getResizedRange(0, headers.length - 1).values = [headers];

        // Set data starting from row 2
        const rows = allData.map(row => Object.values(row));
        sheet.getRange("A2").getResizedRange(rows.length - 1, headers.length - 1).values = rows;

        sheet.activate();
        await context.sync();
      });
    } catch (error) {
      console.error("Error fetching table data:", error);
    }
  });
}



async function fetchSqlData() {
  const baseUrl = document.getElementById("baseUrl").value;
  const sqlQuery = document.getElementById("sqlQuery").value;
  const sqlSheetName = document.getElementById("sqlName").value;
  const accessToken = document.getElementById("accessToken").value;

  try {
    let allData = [];
    let nextUrl = `${baseUrl}/looker/query/data?query=${encodeURIComponent(sqlQuery)}`;

    // Function to fetch data recursively
    async function fetchBatchData(url) {
      const response = await fetch(url, {
        headers: {
          'authorization': `${accessToken}`,  // Ensure you are including the access token correctly
        },
      });

      if (!response.ok) {
        throw new Error('Network response was not ok ' + response.statusText);
      }

      const apiResponse = await response.json();
      allData = allData.concat(apiResponse.data);

      if (apiResponse.next) {
        await fetchBatchData(apiResponse.next);
      }
    }

    // Fetch all data batches
    await fetchBatchData(nextUrl);

    // Process and add the data to Excel
    await Excel.run(async (context) => {
      let sheetName = sqlSheetName;
      context.sync();

      const sheet = context.workbook.worksheets.add(sheetName);

      // Set headers in row 1
      const headers = Object.keys(allData[0]);
      sheet.getRange("A1").getResizedRange(0, headers.length - 1).values = [headers];

      // Set data starting from row 2
      const rows = allData.map(row => Object.values(row));
      sheet.getRange("A2").getResizedRange(rows.length - 1, headers.length - 1).values = rows;

      sheet.activate();
      return context.sync();
    });
  } catch (error) {
    console.error("Error fetching SQL data:", error);
  }
}





